import os
os.environ["CXX"] = "hipcc"

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_reduce_cpp = """
#include &lt;hip/hip_runtime.h&gt;

__global__ void fused_reduce_kernel(const float* x, float* out, int B, int N, int k, float scale, int M) {
    int b = blockIdx.x;
    if (b &gt;= B) return;
    int tx = threadIdx.x;
    const int TPB = 512;
    __shared__ float partial_sums[TPB];
    float thread_sum = 0.0f;
    const float* row = x + b * N;
    for (int i = tx; i &lt; M; i += TPB) {
        float max_val = row[i * k];
        for (int j = 1; j &lt; k; ++j) {
            max_val = ::fmaxf(max_val, row[i * k + j]);
        }
        thread_sum += max_val;
    }
    partial_sums[tx] = thread_sum;
    __syncthreads();
    for (int s = TPB / 2; s &gt; 0; s &gt;&gt;= 1) {
        if (tx &lt; s) {
            partial_sums[tx] += partial_sums[tx + s];
        }
        __syncthreads();
    }
    if (tx == 0) {
        out[b] = partial_sums[0] * scale;
    }
}

torch::Tensor fused_reduce_hip(torch::Tensor x, int64_t kernel_size_, float scale) {
    int64_t B = x.size(0);
    int64_t N = x.size(1);
    int64_t k = kernel_size_;
    int64_t M = N / k;
    torch::Tensor out = torch::zeros({B}, x.options());
    const int TPB = 512;
    dim3 grid(static_cast&lt;unsigned int&gt;(B));
    dim3 block(TPB);
    fused_reduce_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(x.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), static_cast&lt;int&gt;(B), static_cast&lt;int&gt;(N), static_cast&lt;int&gt;(k), scale, static_cast&lt;int&gt;(M));
    return out;
}
"""

fused_reduce = load_inline(
    name="fused_reduce",
    cpp_sources=fused_reduce_cpp,
    functions=["fused_reduce_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor

    def forward(self, x):
        x = self.linear(x)
        return fused_reduce.fused_reduce_hip(x, self.kernel_size, self.scale_factor)

